// Validate that program_name was provided
const body = $input.first().json;

if (!body.program_name || body.program_name.trim() === '') {
    throw new Error('program_name is required in request body');
}

return [{
    json: {
        program_name: body.program_name.trim(),
        request_time: new Date().toISOString(),
        options: body.options || {}
    }
}];

const response = $input.first().json;
const requestData = $('Validate Input').first().json;

// Extract playbook content
const playbook = response.playbook || response.analysis || response;

// Create formatted output
const output = {
    success: true,
    program: requestData.program_name,
    generated_at: new Date().toISOString(),
    executive_summary: typeof playbook === 'string'
        ? playbook.substring(0, 500) + (playbook.length > 500 ? '...' : '')
        : playbook.summary || 'Playbook generated successfully',
    sections: {
        overview: playbook.overview || null,
        key_contacts: playbook.key_contacts || [],
        competitive_landscape: playbook.competitive_landscape || null,
        recommended_actions: playbook.recommended_actions || [],
        timeline: playbook.timeline || null
    },
    full_playbook: playbook,
    metadata: {
        request_time: requestData.request_time,
        processing_time_ms: Date.now() - new Date(requestData.request_time).getTime()
    }
};

return [{ json: output }];

